-- MySQL 8.4 initial import. Requires a completely empty target database.
-- No DROP, REPLACE, user creation or credentials are included.
SET NAMES utf8mb4;

CREATE TABLE cms_content (
	id VARCHAR(36) NOT NULL, 
	kind VARCHAR(24) NOT NULL, 
	slug VARCHAR(191) NOT NULL, 
	identity VARCHAR(220) NOT NULL, 
	shared JSON NOT NULL, 
	version INTEGER NOT NULL, 
	revision INTEGER NOT NULL, 
	translations JSON NOT NULL, 
	published JSON NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (identity)
)ENGINE=InnoDB CHARSET=utf8mb4 COLLATE utf8mb4_unicode_ci

;
CREATE INDEX ix_cms_content_kind ON cms_content (kind);

CREATE TABLE cms_translation_jobs (
	id VARCHAR(36) NOT NULL, 
	content_id VARCHAR(36) NOT NULL, 
	version INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	attempts INTEGER NOT NULL, 
	error TEXT NOT NULL, 
	created_at BIGINT NOT NULL, 
	claimed_at INTEGER NOT NULL, 
	PRIMARY KEY (id)
)ENGINE=InnoDB CHARSET=utf8mb4 COLLATE utf8mb4_unicode_ci

;
CREATE INDEX ix_cms_translation_jobs_content_id ON cms_translation_jobs (content_id);
CREATE INDEX ix_cms_translation_jobs_status ON cms_translation_jobs (status);

CREATE TABLE inquiries (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	region VARCHAR(8) NOT NULL, 
	company VARCHAR(160) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	subject VARCHAR(200) NOT NULL, 
	email VARCHAR(254) NOT NULL, 
	message TEXT NOT NULL, 
	locale VARCHAR(2) NOT NULL, 
	privacy BOOL NOT NULL, 
	created_at DATETIME(6) NOT NULL, 
	PRIMARY KEY (id)
)ENGINE=InnoDB CHARSET=utf8mb4 COLLATE utf8mb4_unicode_ci

;
START TRANSACTION;
COMMIT;
